#include "stdafx.h"#include "..\MnemoWnd.h"#include "Queue.h"#include "..\Lang.h"#define dBadValue (-DBL_MAX/2)//// Обработка кнопок//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структураtypedef struct : public SPROLOZ  {  int nTag;  } Queue_ShowAlarmLimits;   static void DrawElem(HDC hDC, RECT rcLH, int ddY, char *txt, double dVol){   ::DrawText( hDC, txt, -1, &rcLH, DT_SINGLELINE|DT_VCENTER|DT_LEFT);   ::OffsetRect(&rcLH, 0, ddY);   ::SetTextColor(hDC, RGB(0,0,128));   char *format="%1.2f";   if(dVol > 999.9)     format="%2.0f";   else if(dVol > 99.9)     format="%2.1f";    char str[256];   sprintf_s( str, format, dVol);   ::DrawText( hDC, str, -1, &rcLH, DT_SINGLELINE|DT_VCENTER|DT_RIGHT);}// Функция отображенияint PaintShowAlarmLimits(DefinePaint)  {	QueueP(Queue_ShowAlarmLimits);    //	RECT rc = p->mRect;	double dHH = TegValueD( p->nTag, "HH", dBadValue );	double dH = TegValueD( p->nTag, "H", dBadValue );	double dLL = TegValueD( p->nTag, "LL", dBadValue );	double dL = TegValueD( p->nTag, "L", dBadValue );    int dY=rc.bottom-rc.top;    int ddY=dY/8;    int y=rc.top;    RECT rcLH(rc);    rcLH.bottom=rcLH.top+ddY;     COLORREF oldcolor=::GetTextColor(hDC);    if (dHH!=dBadValue)    {           ::SetTextColor(hDC, RGB(255,0,0));       DrawElem(hDC, rcLH, ddY, "HH", dHH);    }    ::OffsetRect(&rcLH, 0, 2*ddY);    if (dH!=dBadValue)    {       ::SetTextColor(hDC, RGB(255,255,0));       DrawElem(hDC, rcLH, ddY, "H", dH);    }    ::OffsetRect(&rcLH, 0, 2*ddY);	if (dL!=dBadValue)    {       ::SetTextColor(hDC, RGB(255,255,0));       DrawElem(hDC, rcLH, ddY, "L", dL);    }    ::OffsetRect(&rcLH, 0, 2*ddY);	if (dLL!=dBadValue)    {       ::SetTextColor(hDC, RGB(255,0,0));       DrawElem(hDC, rcLH, ddY, "LL", dLL);    }    ::SetTextColor(hDC, oldcolor);   return 0;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddShowAlarmLimits(DefineTegs)  {  //  AddQueueEx(Queue_ShowAlarmLimits);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  p->paint = &PaintShowAlarmLimits;  p->nNumber=-1;  p->nTag=-1;  STegObj obj[] =    {    { 'R', "rect"   , &p->mRect  },    { 'E', "rc"     , &p->mRect  },    EXT_QUEUE  // Дополнительная информация    //    };  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  p->nTag = ::FindTagEx( teg[0].value, id_Sensor );  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~